    {
        int err_warn[2];
        res->ret = arm->get_err_warn_code(err_warn);
        res->datas.resize(2);
        res->datas[0] = err_warn[0];
        res->datas[1]= err_warn[1];
        res->message = "datas=[ " + std::to_string(res->datas[0]) + ", " + std::to_string(res->datas[1]) + " ]";
        return true;
    }

